{
  "items": [
    {
      "title": "Decrease WARMUP_RATIO",
      "spec": "Change WARMUP_RATIO from 0.0 to 1.0 to stabilize initial gradients without further LR reduction, and adjust WARMDOWN_RATIO to 0.7 to maintain longer LR decay.",
      "family": "schedule"
    },
    {
      "title": "Increase WEIGHT_DECAY",
      "spec": "Change WEIGHT_DECAY from 0.2 to 0.5 to strengthen regularization and reduce overfitting on the validation set.",
      "family": "regularization"
    },
    {
      "title": "Increase SCALAR_LR",
      "spec": "Change SCALAR_LR from 0.5 to 1.0 to decrease per-unit update magnitude as vector lengths approach infinity, theoretically stabilizing convergence.",
      "family": "optimizer"
    },
    {
      "title": "Decrease HEAD_DIM",
      "spec": "Change HEAD_DIM from 128 to 64 to reduce parameter count and model capacity per layer.",
      "family": "architecture"
    },
    {
      "title": "Decrease ASPECT_RATIO",
      "spec": "Change ASPECT_RATIO from 64 to 60 to reduce model width while keeping depth fixed, lowering total FLOPs per step.",
      "family": "architecture"
    },
    {
      "title": "Increase EM Buddhism LR",
      "spec": "Increase EMBEDDING_LR from 0.6 to 5.0 to accelerate token embeddings significantly while keeping matrix updates conservative.",
      "family": "optimizer"
    },
    {
      "title": "Increase UNEMBEDDING_LR",
      "spec": "Increase UNEMBEDDING_LR from 0.004 to 0.01 to accelerate loss initialization dynamics during early training.",
      "family": "optimizer"
    },
    {
      "title": "Increase DEVICE_BATCH_SIZE",
      "spec": "Attempt to increase DEVICE_BATCH_SIZE from 64 to 128 by emptying EXACT_BATCH_SIZE constraints (evaluate if partial batch handling is possible or if out-of-poem error requires more changes)",
      "family": "batch"
    },
    {
      "title": "Add Adam W0.1",
      "spec": "Add Adam scaling of 0.0 to matrix parameters to better match matrix magnitude",
      "family": "regularization"
    },
    {
      "title": "Double HALF_DIM (baseline SS)",
      "spec": "Reduce HALF_DIM to 64 in context to decrease model capacity within the existing constraints",
      "family": "architecture"
    }
  ]
}

{
  "items": [
