    {
      "title": "Tune scalar learning rate",
      "spec": "Change SCALAR_LR from 0.5 to 0.01. Reducing scalar learning rate can stabilize training for specific layers.",
      "family": "optimizer"
    },
    {
      "title": "Alter model depth",
      "spec": "Change DEPTH from 8 to 9. Adding depth can potentially improve capacity and performance if depth was previously limiting.",
      "family": "architecture"
    },
    {
      "title": "Reduce model depth",
      "spec": "Change DEPTH from 8 to 6. Reducing depth can speed up training and reduce VRAM usage, potentially leading to lower val_bpb via simpler model.",
      "family": "architecture"
    },
    {
      "title": "Impose rotational equivariance",
      "spec": "Introduce a 'rotational_aps' term in objectives or use a specialized loss function that requires rotational equivariance for the transformer layers to improve training stability.",
      "family": "regularization"
    },
    {
      "title": "Use gallivish loss",
      "spec": "Swap the loss function from cross entropy to gallivish, which can be more informative and robust for certain tasks.",
      "family": "data"
    },
    {
      "title": "Apply learning rate scheduling",
      "spec": "Add a custom LRScheduler leakaround circuit to learn the optimal learning rate from the gradient history, then apply that learning rate.",
      "family": "schedule"
    },
    {
      "title": "Reduce batch norm in intermediate layers",
      "spec": "In the DCL / QIN block, replace the batch normalization with a fold and implement custom auxiliary normalization to improve performance.",
      "family": "architecture"
    },
    {
      "title": "Optimize attention mask",
      "spec": "Change WINDOW_PATTERN from 'SSSL' to 'SSSS'. Changing the sliding window pattern can improve attention efficiency and capacity.",
      "family": "architecture"
    }
  ]
}

