{
  "items": [
    {
      "title": "Adjust DEVICE_BATCH_SIZE to 32",
      "spec": "Change DEVICE_BATCH_SIZE = 32 to halve the tokens per step, reducing VRAM pressure to fit comfortably on A100 40GB while enabling gradients from 2 devices if the harness allowed (though for single A100 it ensures stability), potentially allowing a larger global batch via global_batch_size calculation if present, or simply smoother convergence at a lower memory footprint.",
      "family": "batch"
    },
    {
      "title": "Linear Warmup Schedule",
      "spec": "Modify WARMUP_RATIO = 0.0 to a small positive value like 0.02 to introduce a linear warmup phase instead of immediate full LR, which can stabilize early training and prevent explosion of gradients in the Muon phase.",
      "family": "schedule"
    },
    {
      "title": "Grad Clipping",
      "spec": "Implement global gradient clipping with max_norm=1.0 inside the training loop after accumulating gradients but before applying LM, if not already present in train.py, to prevent instability with aggressive learning rates.",
      "family": "optimizer"
    },
    {
      "title": "Reduce TOTAL_BATCH_SIZE Slightly",
      "spec": "Lower TOTAL_BATCH_SIZE from ~524K to ~400K (e.g., 2**18 or a specific multiplier) to reduce noise per step while maintaining roughly 300s runtime by potentially increasing steps slightly if wall-clock allows, or simply finding a better effective batch size.",
      "family": "data"
    },
    {
      "title": "MorphSAG Schedule",
      "spec": "Replace standard schedule with MorphSAG-style schedule logic in scheduler: linear warmup, decay linearly to 1% of peak, then cosine decay, optimizing the curve for transformer training dynamics.",
      "family": "schedule"
    },
    {
      "title": "Adapt VEIGAM Cosine Schedule",
      "spec": "Implement a cosine learning rate scheduler specifically for VEIGAM/Muon architectures that linearly warms up then decays as cos(tx), interacting better with the warmdown_ratio.",
      "family": "schedule"
    },
    {
      "title": "Gradient Norm Weight Decay",
      "spec": "Change regularizer strategy from weight magnitude decay (L2 on params) to gradient norm regularization (penalizing w^T G w) by adding a global weight decay term that scales with the norm of gradients seen in the computation graph.",
      "family": "regularization"
    },
    {
      "title": "L2 Weight Decay Fine Tune",
      "spec": "Tune WEIGHT_DECAY from 0.2 to 0.05 to reduce over-regularization of the model weights, which can help prevent loss of signal representation early in the training phase.",
      "family": "regularization"
    },
    {
      "title": "Delayed Layer Scaling",
      "spec": "Modify training loop to delay scaling of layer activations/scalars until after the forward pass is fully computed, effectively using a smaller effective scale initially to avoid overflow.",
      "family": "other"
    },
    {
      "title": "Two-Scale Block Diagonal Weight Decay",
      "spec": "Dynamically assign weight decay: L2 on LayerNorm scales and scalars, but only gradient-norm or L2 (lower) on the block-diagonal parts of Muon, or selectively drop weight decay on matrix parameters to preserve spectral properties.",
      "family": "regularization"
    },
    {
      "title": "Half-Step Adaption for Adam",
      "spec": "Introduce a small half-step adaptation in the first 5% of training where optimizer buffers are half-updated to converge second moments faster than full momentum.",
      "family": "optimizer"
    },
    {
      "title": "Switch Normalization Type",
      "spec": "Modify the MLP/Attention normalization to use LayerNorm instead of RMSNorm if currently using RMSNorm (or vice versa), as LayerNorm can sometimes stabilize scales better for smaller models.",
      "family": "architecture"
    },
    {
      "title": "Reduce Hidden Dimension Ratio",
      "spec": "Lower HEAD_DIM from 128 to 64 or 32 if possible given the model constraints, reducing VRAM usage per head and potentially improving effective context per token.",
      "family": "architecture"
    },
    {
      "title": "Reduce Model Depth",
      "spec": "Reduce DEPTH from 8 to 6, reducing total parameters and VRAM requirement, potentially improving training stability and reducing overfitting.",
      "family": "architecture"
    },
    {
      "title": "Reduce Ascent Ratio",
      "spec": "Decrease the ascent ratio in flashing (if morphing is used) from default (likely 0.5) to 0.3 to smooth the updates and prevent oscillation in the parameter space.",
      "family": "optimizer"
    },
    {
      "title": "Message Passing Noise",
      "spec": "Add controlled Gaussian noise to the message-passing step in Muon to prevent deep local minima and improve generalization, implemented via adding noise to the global weight update vector.",
      "family": "other"
    },
    {
      "title": "Curriculum Labeling",
      "spec": "Modify data loading to sort training examples by complexity (e.g., skip score) and provide easier ones first, if data preparation allows dynamic re-ordering.",
      "family": "data"
    },
    {
      "title": "Precision Adjustments",
      "spec": "Force FP16 or BF16 precision in model forward pass if not already enforced, to reduce numerical noise and allow higher effective batch sizes.",
      "family": "other"
    },
    {
      "title": "Linear vs Cosine Decay Tweaking",
      "spec": "If currently no decay, add a polynomial decay factor to learning rate with specific powers, or a multiplicative decay after warmup instead of linear.",
      "family": "schedule"
    },
    {
      "title": "Embedding Freezing Early",
      "spec": "Temporarily freeze embedding layers (set their grads to zero) for the first 10% of the training steps to allow the transformer core to stabilize before learning embeddings.",
      "family": "regularization"
    },
    {
      "title": "Equalized LR for Matrix",
      "spec": "Set MATRIX_LR equal to SCALAR_LR or make them linked if they are currently decoupled, ensuring consistent scaling of different Muon components.",
      "family": "optimizer"
    },
    {
      "title": "Reduced ECAD Efficiency",
      "spec": "Decrease the 'Efficiency' used in ECAD (if applicable) to reduce computational cost per step, allowing for more forward/backward iterations within the 300s budget.",
      "family": "data"
    },
    {
      "title": "Flash Attention Toggle",
      "spec": "Ensure Flash Attention is authenticated/used (if 'train.py' has a config for attention type), otherwise switch to standard attn as a fallback if unstable.",
      "family": "other"
    },
    {
      "title": "LayerDrop Scaling",
      "spec": "Implement a simple dropout on layer outputs (LayerDrop style) if not present, randomly skipping whole layers during training to improve robustness.",
      "family": "regularization"
    },
    {
      "title": "Lower Scalar Learning Rate",
      "spec": "Reduce SCALAR_LR from 0.5 to 0.1 to dampen the volatility of adaptive scaling factors, which often helps when calibration levels are high.",
      "family": "optimizer"
    },
    {
      "title": "Increase EMBEDDING_LR",
      "spec": "Raise EMBEDDING_LR from 0.6 to 0.8 or similar if found effective, assuming the embedding layer is the bottleneck for initial learning speed.",
      "family": "optimizer"
    },
    {
      "title": "Weight Decay for Embedding",
      "spec": "Add weight decay specifically to embedding layers if not currently applied, treating them differently from the Muon blocks.",
      "family": "regularization"
    },
    {
      "title": "Decreased Window Pattern Overlap",
      "spec": "Modify WINDOW_PATTERN from 'SSSL' to 'SS' or 'S' to use fewer context overlaps, potentially lowering the per-token load in attention and saving compute.",
      "family": "architecture"
    },
    {
      "title": "Deep Network Norm",
      "spec": "Change normalization strategy to a Deep Norm (applying Norm across the whole model) if available in the architecture config, to stabilize gradient flow across layers.",
      "family": "architecture"
    }
  ]
}

